// 1. Destructure the parameters from the single options object.
const {
    page,
    limit,
    query,
    clearCache,
    entity: entityFromOptions, // Use an alias to avoid conflict with the final entityType
    apiType,
    customEntityKey
} = options;

// 2. Determine the final entityType, preferring the one from options,
//    then falling back to the service's current state. This preserves your original logic.
const entityType = entityFromOptions ?? this.entityType;
const columnConfig = this.displayColumnConfig;

// Uncomment and adapt this if you need to clear the cache.
// It might be better to clear only the specific cache key.
// if (clearCache) {
//     this.entityCacheService.clearCacheFor(entityType);
// }

// 3. The core logic remains the same. It just uses the destructured variables.
const entityAction = this.utilityService.buildEntityAction(entityType, "SelectAll");

// Pass the extracted parameters to the cache service.
return this.entityCacheService.getAll(
    entityAction,
    entityType,
    page,
    limit,
    columnConfig,
    query,
    apiType,
    customEntityKey
);

const entityType = this.entityType;

// if (clearCache) this.entityCacheService.clearCache();
const entityActivities = await this.activityService.getAllActivitiesByEntityByEntityId(page, limit, entityType, entityId, activityType, query);
entityActivities.ownerId = entityId;

return entityActivities;

const titleCasedEntityType = this.entityType[0].toUpperCase() + this.entityType.slice(1);
const entityActivities = this.activityService.getCachedActivities(activityType, titleCasedEntityType, entityId);

return this.utilityService.sortEntitiesByDateProperty(entityActivities, "createdOn");

try {
    if (columns) {
        const cachedEntry = this.entityCacheService.getCachedEntry(this.entityType);

        if (cachedEntry) {
            cachedEntry.columns = columns;
            this.entityCacheService.setCachedEntry(this.entityType, cachedEntry);
        }

    }
} catch (e) {
    console.error("Error setting cached entity columns: ", e);
}
